#[cfg(test)]
mod prepared_generator {
    //! Prints the Rust source of `PREPARED_G2_GENERATOR` and `PREPARED_G2_BY_TAU` (their lines
    //! normalized to a first coefficient of one) in both representations; run with
    //! `cargo test -p airbender-crypto --lib print_prepared_g2 -- --nocapture --ignored`
    use crate::bls12_381::consts::G2_BY_TAU_POINT;
    use crate::bls12_381::curves::G2PreparedNoAlloc;
    use ark_ff::{Field, One, PrimeField};

    fn conv(x: crate::bls12_381::Fq) -> ark_bls12_381::Fq {
        let mut limbs = [0u64; 6];
        limbs.copy_from_slice(&x.into_bigint().0[..6]);
        ark_bls12_381::Fq::from_bigint(ark_ff::BigInt(limbs)).unwrap()
    }

    fn conv_back(x: ark_bls12_381::Fq) -> crate::bls12_381::Fq {
        let mut limbs = [0u64; 8];
        limbs[..6].copy_from_slice(&x.into_bigint().0);
        crate::bls12_381::Fq::from_bigint(crate::BigInt(limbs)).unwrap()
    }

    fn tau_ref() -> ark_bls12_381::G2Affine {
        let tau = G2_BY_TAU_POINT;
        let tau_ref = ark_bls12_381::G2Affine::new_unchecked(
            ark_bls12_381::Fq2::new(conv(tau.x.c0), conv(tau.x.c1)),
            ark_bls12_381::Fq2::new(conv(tau.y.c0), conv(tau.y.c1)),
        );
        assert!(tau_ref.is_on_curve() && tau_ref.is_in_correct_subgroup_assuming_on_curve());
        tau_ref
    }

    /// The lines of `q` (the reference implementation), each divided by its first coefficient
    fn normalized_lines(
        q: ark_bls12_381::G2Affine,
    ) -> Vec<(ark_bls12_381::Fq2, ark_bls12_381::Fq2, ark_bls12_381::Fq2)> {
        ark_ec::bls12::G2Prepared::<ark_bls12_381::Config>::from(q)
            .ell_coeffs
            .iter()
            .map(|(a, b, c)| {
                let inverse = a
                    .inverse()
                    .expect("a line has a non-zero first coefficient");
                (ark_bls12_381::Fq2::ONE, *b * inverse, *c * inverse)
            })
            .collect()
    }

    fn emit(
        out: &mut String,
        name: &str,
        lines: &[(ark_bls12_381::Fq2, ark_bls12_381::Fq2, ark_bls12_381::Fq2)],
    ) {
        let host_rows: Vec<[Vec<u64>; 6]> = lines
            .iter()
            .map(|(a, b, c)| [a.c0, a.c1, b.c0, b.c1, c.c0, c.c1].map(|x| x.0 .0.to_vec()))
            .collect();
        let guest_rows: Vec<[Vec<u64>; 6]> = lines
            .iter()
            .map(|(a, b, c)| {
                [a.c0, a.c1, b.c0, b.c1, c.c0, c.c1].map(|x| conv_back(x).0 .0.to_vec())
            })
            .collect();
        let mut emit_one = |cfg: &str, fp_path: &str, rows: Vec<[Vec<u64>; 6]>| {
            out.push_str(cfg);
            out.push_str(&format!("pub static {name}:\n    <crate::bls12_381::curves::Bls12_381 as crate::ark_ec::pairing::Pairing>::G2Prepared =\n    crate::bls12_381::curves::G2PreparedNoAlloc {{\n        ell_coeffs: [\n"));
            for row in rows {
                out.push_str("            (\n");
                for pair in row.chunks(2) {
                    out.push_str("                crate::ark_ff::fields::models::Fp2 {\n");
                    for (name, limbs) in ["c0", "c1"].iter().zip(pair) {
                        out.push_str(&format!("                    {name}: {fp_path}(\n                        crate::BigInt({limbs:?}),\n                        core::marker::PhantomData,\n                    ),\n"));
                    }
                    out.push_str("                },\n");
                }
                out.push_str("            ),\n");
            }
            out.push_str(
                "        ],\n        infinity: false,\n        normalized: true,\n    };\n\n",
            );
        };
        emit_one(
            "#[cfg(not(any(\n    all(target_arch = \"riscv32\", feature = \"bigint_ops\"),\n    feature = \"proving\",\n    test\n)))]\n",
            "crate::ark_ff::fields::models::Fp",
            host_rows,
        );
        emit_one(
            "#[cfg(any(\n    all(target_arch = \"riscv32\", feature = \"bigint_ops\"),\n    feature = \"proving\",\n    test\n))]\n",
            "crate::ark_ff_delegation::Fp",
            guest_rows,
        );
    }

    #[test]
    #[ignore]
    fn print_prepared_g2() {
        use ark_ec::AffineRepr;
        let mut out = String::new();
        emit(
            &mut out,
            "PREPARED_G2_GENERATOR",
            &normalized_lines(ark_bls12_381::G2Affine::generator()),
        );
        emit(&mut out, "PREPARED_G2_BY_TAU", &normalized_lines(tau_ref()));
        std::fs::write("/tmp/prepared_g2_normalized.rs", out).unwrap();
    }

    /// The constants are the lines of the preparation, normalized
    #[test]
    fn prepared_constants_match_preparation() {
        use ark_ec::AffineRepr;
        for (constant, point) in [
            (
                &crate::bls12_381::consts::PREPARED_G2_GENERATOR,
                crate::bls12_381::G2Affine::generator(),
            ),
            (
                &crate::bls12_381::consts::PREPARED_G2_BY_TAU,
                G2_BY_TAU_POINT,
            ),
        ] {
            let prepared = G2PreparedNoAlloc::from(point);
            assert!(constant.normalized && !constant.infinity);
            for ((a, b, c), (ra, rb, rc)) in constant.ell_coeffs.iter().zip(&prepared.ell_coeffs) {
                assert!(a.is_one());
                assert_eq!(*b * ra, *rb);
                assert_eq!(*c * ra, *rc);
            }
        }
    }

    /// The Miller loop over both pairs at once, with the normalized constant lines, gives the
    /// pairing of the per-pair loop over the plain lines; with an initial value it is the
    /// per-pair loop with that value; a `G1` point at infinity drops its pair
    #[test]
    fn shared_miller_loop_matches() {
        use crate::bls12_381::curves::Bls12_381;
        use crate::bls12_381::{Fq12, G1Affine};
        use ark_ec::pairing::{MillerLoopOutput, Pairing};
        use ark_ec::{AffineRepr, CurveGroup};
        let g1 = |k: u64| (G1Affine::generator() * crate::bls12_381::Fr::from(k)).into_affine();
        let plain = [
            G2PreparedNoAlloc::from(crate::bls12_381::G2Affine::generator()),
            G2PreparedNoAlloc::from(G2_BY_TAU_POINT),
        ];
        let normalized = [
            &crate::bls12_381::consts::PREPARED_G2_GENERATOR,
            &crate::bls12_381::consts::PREPARED_G2_BY_TAU,
        ];
        let final_exponentiation = |f: Fq12| {
            Bls12_381::final_exponentiation(MillerLoopOutput(f))
                .unwrap()
                .0
        };
        for points in [
            [g1(3), g1(5)],
            [G1Affine::identity(), g1(5)],
            [g1(7), G1Affine::identity()],
        ] {
            let expected =
                final_exponentiation(Bls12_381::multi_miller_loop(points, plain.clone()).0);
            let mut f = Bls12_381::multi_miller_loop_shared(None, points.iter().zip(normalized));
            f.conjugate_in_place();
            assert_eq!(final_exponentiation(f), expected);
            // the per-pair loop over the normalized lines agrees too
            let mut f = Bls12_381::multi_miller_loop_prepared(points, normalized);
            assert_eq!(final_exponentiation(f), expected);
            f.conjugate_in_place();
            let element = |k: u64| crate::bls12_381::Fq::from(k);
            let fq2 = |k: u64| crate::bls12_381::Fq2::new(element(k), element(k + 1));
            let fq6 = |k: u64| crate::bls12_381::Fq6::new(fq2(k), fq2(k + 2), fq2(k + 4));
            let d = Fq12::new(fq6(11), fq6(17));
            let with_initial = Bls12_381::multi_miller_loop_with_initial(&d, points, normalized);
            let shared =
                Bls12_381::multi_miller_loop_shared(Some(&d), points.iter().zip(normalized));
            assert_eq!(with_initial, shared);
            let x = <crate::bls12_381::curves::Config as ark_ec::bls12::Bls12Config>::X;
            assert_eq!(shared, f * d.pow(x));
        }
    }
}
